import{_ as n,a as o,c as i,ac as l}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第四册：流利英语 · 全册语法总结 · 推测情态动词与过去事件至情态动词的被动结构","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第四册：流利英语 · 全册语法总结 · 推测情态动词与过去事件至情态动词的被动结构","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-4/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册语法总结","link":"/life/english/new-concept/book-4/grammar"},"next":{"text":"第四册：流利英语 · 全册语法总结 · 过去完成时与过去叙事参照点至同位语从句与定语从句","link":"/life/english/new-concept/book-4/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册语法总结","link":"/life/english/new-concept/book-4/grammar"},"next":{"text":"第四册：流利英语 · 全册语法总结 · 过去完成时与过去叙事参照点至同位语从句与定语从句","link":"/life/english/new-concept/book-4/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-4/grammar-part-01.md","filePath":"life/english/new-concept/book-4/grammar-part-01.md"}'),a={name:"life/english/new-concept/book-4/grammar-part-01.md"};function t(s,e,r,h,c,p){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第四册-流利英语-·-全册语法总结-·-推测情态动词与过去事件至情态动词的被动结构" tabindex="-1">第四册：流利英语 · 全册语法总结 · 推测情态动词与过去事件至情态动词的被动结构 <a class="header-anchor" href="#第四册-流利英语-·-全册语法总结-·-推测情态动词与过去事件至情态动词的被动结构" aria-label="Permalink to &quot;第四册：流利英语 · 全册语法总结 · 推测情态动词与过去事件至情态动词的被动结构&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="第四册-流利英语-·-全册语法总结" tabindex="-1">第四册：流利英语 · 全册语法总结 <a class="header-anchor" href="#第四册-流利英语-·-全册语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 全册语法总结 {#第四册-流利英语-·-全册语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="按知识点查阅" tabindex="-1">按知识点查阅 <a class="header-anchor" href="#按知识点查阅" aria-label="Permalink to &quot;按知识点查阅 {#按知识点查阅}&quot;">​</a></h2><ul><li>推测情态动词与过去事件：<a href="/life/english/new-concept/book-4/unit-01/lesson-001">L1</a></li><li>数量词与可数性：<a href="/life/english/new-concept/book-4/unit-01/lesson-002">L2</a></li><li>used to、would 与过去状态：<a href="/life/english/new-concept/book-4/unit-01/lesson-003">L3</a></li><li>报告动词与认知距离：<a href="/life/english/new-concept/book-4/unit-01/lesson-004">L4</a></li><li>让步从句与主句重心：<a href="/life/english/new-concept/book-4/unit-01/lesson-005">L5</a></li><li>not so much A as B 的纠正性对比：<a href="/life/english/new-concept/book-4/unit-01/lesson-006">L6</a></li><li>关系从句中的指代与功能说明：<a href="/life/english/new-concept/book-4/unit-01/lesson-007">L7</a></li><li>情态动词的被动结构：<a href="/life/english/new-concept/book-4/unit-01/lesson-008">L8</a></li><li>过去完成时与过去叙事参照点：<a href="/life/english/new-concept/book-4/unit-02/lesson-009">L9</a></li><li>比较结构与范围限定：<a href="/life/english/new-concept/book-4/unit-02/lesson-010">L10</a></li><li>动名词短语作主语：<a href="/life/english/new-concept/book-4/unit-02/lesson-011">L11</a></li><li>unless 与条件从句：<a href="/life/english/new-concept/book-4/unit-02/lesson-012">L12</a></li><li>目的不定式与 so that：<a href="/life/english/new-concept/book-4/unit-02/lesson-013">L13</a></li><li>第二条件句与假设距离：<a href="/life/english/new-concept/book-4/unit-02/lesson-014">L14</a></li><li>whether 引导名词性从句：<a href="/life/english/new-concept/book-4/unit-02/lesson-015">L15</a></li><li>so…that 与 such…that 的结果表达：<a href="/life/english/new-concept/book-4/unit-02/lesson-016">L16</a></li><li>cause、lead to 与 be associated with：<a href="/life/english/new-concept/book-4/unit-03/lesson-017">L17</a></li><li>感官动词的主动与被动转换：<a href="/life/english/new-concept/book-4/unit-03/lesson-018">L18</a></li><li>同位语从句与定语从句：<a href="/life/english/new-concept/book-4/unit-03/lesson-019">L19</a></li><li>过去分词作后置定语：<a href="/life/english/new-concept/book-4/unit-03/lesson-020">L20</a></li><li>It is/was…that 强调句：<a href="/life/english/new-concept/book-4/unit-03/lesson-021">L21</a></li><li>what 从句作主语与表语：<a href="/life/english/new-concept/book-4/unit-03/lesson-022">L22</a></li><li>现在分词状语与逻辑主语：<a href="/life/english/new-concept/book-4/unit-03/lesson-023">L23</a></li><li>否定或限制副词前置倒装：<a href="/life/english/new-concept/book-4/unit-03/lesson-024">L24</a></li><li>名词化与施事信息：<a href="/life/english/new-concept/book-4/unit-04/lesson-025">L25</a></li><li>完成式分词状语：<a href="/life/english/new-concept/book-4/unit-04/lesson-026">L26</a></li><li>第三条件句与过去反事实：<a href="/life/english/new-concept/book-4/unit-04/lesson-027">L27</a></li><li>间接问句与疑问语序：<a href="/life/english/new-concept/book-4/unit-04/lesson-028">L28</a></li><li>使役与许可结构：<a href="/life/english/new-concept/book-4/unit-04/lesson-029">L29</a></li><li>介词 + which 的关系从句：<a href="/life/english/new-concept/book-4/unit-04/lesson-030">L30</a></li><li>独立主格的主语与分词：<a href="/life/english/new-concept/book-4/unit-04/lesson-031">L31</a></li><li>形容词前置的 as 让步结构：<a href="/life/english/new-concept/book-4/unit-04/lesson-032">L32</a></li><li>平行结构与 not only…but also：<a href="/life/english/new-concept/book-4/unit-05/lesson-033">L33</a></li><li>倾向表达与概率范围：<a href="/life/english/new-concept/book-4/unit-05/lesson-034">L34</a></li><li>将来完成时与未来截止点：<a href="/life/english/new-concept/book-4/unit-05/lesson-035">L35</a></li><li>倍数比较与百分比基数：<a href="/life/english/new-concept/book-4/unit-05/lesson-036">L36</a></li><li>比较级重复与渐变表达：<a href="/life/english/new-concept/book-4/unit-05/lesson-037">L37</a></li><li>if、when 后的省略结构：<a href="/life/english/new-concept/book-4/unit-05/lesson-038">L38</a></li><li>wish 后的时态与非现实意义：<a href="/life/english/new-concept/book-4/unit-05/lesson-039">L39</a></li><li>where 的地点与条件意义：<a href="/life/english/new-concept/book-4/unit-05/lesson-040">L40</a></li><li>with + 宾语 + 补足语：<a href="/life/english/new-concept/book-4/unit-06/lesson-041">L41</a></li><li>被动语态中的时态与体：<a href="/life/english/new-concept/book-4/unit-06/lesson-042">L42</a></li><li>there be 与存在命题：<a href="/life/english/new-concept/book-4/unit-06/lesson-043">L43</a></li><li>限制性与非限制性从句的范围差异：<a href="/life/english/new-concept/book-4/unit-06/lesson-044">L44</a></li><li>no more than 与 not more than：<a href="/life/english/new-concept/book-4/unit-06/lesson-045">L45</a></li><li>would rather 与 prefer 的补语：<a href="/life/english/new-concept/book-4/unit-06/lesson-046">L46</a></li><li>篇章指代与 this + 概括名词：<a href="/life/english/new-concept/book-4/unit-06/lesson-047">L47</a></li><li>决策段落中的 however、therefore 与条件：<a href="/life/english/new-concept/book-4/unit-06/lesson-048">L48</a></li></ul><h2 id="推测情态动词与过去事件" tabindex="-1">推测情态动词与过去事件 <a class="header-anchor" href="#推测情态动词与过去事件" aria-label="Permalink to &quot;推测情态动词与过去事件 {#推测情态动词与过去事件}&quot;">​</a></h2><p>must have done 表示依据现有证据对过去作出较强推断，might have done 表示一种可能性，cannot have done 表示认为过去不可能如此。它们都不是对过去事实的直接报告。说明化石年代时，应先给观察再给推论；证据不足就不宜使用 must。must have left 不等于 had to leave，前者是推断离开过，后者是过去不得不离开。</p><p><strong>L1 原创例句：</strong> The marks might have been made by tools, but their origin remains uncertain.</p><p>这些痕迹可能是工具留下的，但其来源仍不确定。</p><p><strong>易错：</strong> 不要把 might have been made 译成“必定是造成的”；might 保留了其他解释。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">Lesson 1</a></p><h2 id="数量词与可数性" tabindex="-1">数量词与可数性 <a class="header-anchor" href="#数量词与可数性" aria-label="Permalink to &quot;数量词与可数性 {#数量词与可数性}&quot;">​</a></h2><p>fewer 修饰可数名词复数，less 通常修饰不可数名词；a number of 后面接复数谓语，the number of 则把数量视为整体，接单数谓语。insects 是可数名词，damage 通常不可数。生态比较还必须交代比较对象和时间范围；fewer insects 只说明数量较少，不自动证明差异由蜘蛛造成。相关观察与因果解释应分开表达。</p><p><strong>L2 原创例句：</strong> The number of insects was lower in the sheltered garden.</p><p>避风花园中的昆虫数量较少。</p><p><strong>易错：</strong> The number of insects were lower 错在主谓一致；但 A number of insects were found 中复数正确。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">Lesson 2</a></p><h2 id="used-to、would-与过去状态" tabindex="-1">used to、would 与过去状态 <a class="header-anchor" href="#used-to、would-与过去状态" aria-label="Permalink to &quot;used to、would 与过去状态 {#used-to、would-与过去状态}&quot;">​</a></h2><p>used to 可以描述过去的习惯，也可以描述如今不再成立的状态；would 叙述过去反复发生的动作时，需要已建立的过去时间背景。描述过去住在哪里等静态情况，通常用 used to live，而不是单独用 would live。一次特定登山经历用一般过去时。否定形式 did not use to 中 use 不加 d，疑问句同样由 did 承担过去时标记。</p><p><strong>L3 原创例句：</strong> The village used to be quiet, but each summer guides would welcome new climbers.</p><p>村庄过去很安静，但每年夏天向导们都会迎接新的登山者。</p><p><strong>易错：</strong> 不要用 would be quiet 无背景地替代 used to be quiet；would 还可能被理解为条件结果。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">Lesson 3</a></p><h2 id="报告动词与认知距离" tabindex="-1">报告动词与认知距离 <a class="header-anchor" href="#报告动词与认知距离" aria-label="Permalink to &quot;报告动词与认知距离 {#报告动词与认知距离}&quot;">​</a></h2><p>claim that 表示提出主张，不表示说话者认可主张；report that 表示报告内容，其可靠性仍需评估。be said to 和 be reported to 将信息归于他人，可接 to have done 表示更早发生的动作。写历史科学材料时，不能把 is claimed to 改写成 can 而保持相同证据强度。实验主张应区分来源、方法、结果和可重复性；语法上的被动结构本身不增加可信度。</p><p><strong>L4 原创例句：</strong> The participant was reported to have identified the colour, but the test did not rule out visual cues.</p><p>据报告参与者辨认出了颜色，但实验没有排除视觉线索。</p><p><strong>易错：</strong> “was reported to identify”不是“被证实能够辨认”；reported 与 proved 的证据含义不同。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">Lesson 4</a></p><h2 id="让步从句与主句重心" tabindex="-1">让步从句与主句重心 <a class="header-anchor" href="#让步从句与主句重心" aria-label="Permalink to &quot;让步从句与主句重心 {#让步从句与主句重心}&quot;">​</a></h2><p>although 和 even though 引导让步从句，后面需要主语和谓语；despite 后接名词或动名词，不能直接接普通完整句。主句承载作者仍然坚持的判断，前面的让步不是取消主句。Although young people lack some experience, they can offer new ideas. 中承认经验不足，但重点是新想法。英语通常不在同一句使用 although 与 but 双重连接两个分句。</p><p><strong>L5 原创例句：</strong> Although Lena had little experience, the team took her proposal seriously.</p><p>虽然莉娜经验不多，团队仍认真考虑了她的提议。</p><p><strong>易错：</strong> Although she was young, but she led the discussion. 应去掉 but；despite her youth 则不需要主谓结构。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">Lesson 5</a></p><h2 id="not-so-much-a-as-b-的纠正性对比" tabindex="-1">not so much A as B 的纠正性对比 <a class="header-anchor" href="#not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;not so much A as B 的纠正性对比 {#not-so-much-a-as-b-的纠正性对比}&quot;">​</a></h2><p>not so much A as B 表示与其说是 A，不如说是 B，重点在 B，不等于 A 和 B 一样多。A 与 B 最好保持语法平行，可以都是名词、动名词或形容词短语。The dispute was not so much about rules as about pride. 中两个 about 短语相互对应。此结构通常降低 A 的解释权重，并不一定完全否定 A；翻译时不能机械处理成数量比较。</p><p><strong>L6 原创例句：</strong> The argument was not so much about the score as about respect.</p><p>这场争论与其说是关于比分，不如说是关于尊重。</p><p><strong>易错：</strong> 不要将 not so much A as B 理解成“不如 A 那么 B”；它在两个解释之间强调后者。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">Lesson 6</a></p><h2 id="关系从句中的指代与功能说明" tabindex="-1">关系从句中的指代与功能说明 <a class="header-anchor" href="#关系从句中的指代与功能说明" aria-label="Permalink to &quot;关系从句中的指代与功能说明 {#关系从句中的指代与功能说明}&quot;">​</a></h2><p>which 可以指物，who 指人；限制性关系从句帮助确定是哪一个对象，非限制性关系从句用逗号补充信息。The echoes that return first provide one clue. 中 that return first 限定 echoes。关系代词作主语时不能省略；作宾语时在限制性从句中通常可省。写机制说明时要让 which 紧靠明确先行词，避免读者不知它指声音、动物还是整个过程。</p><p><strong>L7 原创例句：</strong> The device measures the delay between a signal and the echo that returns from the wall.</p><p>这个装置测量信号与墙壁返回的回声之间的时间差。</p><p><strong>易错：</strong> 不能把 the echo that returns 写成 the echo returns 后仍接在原宾语位置；省略主语关系词会破坏结构。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">Lesson 7</a></p><h2 id="情态动词的被动结构" tabindex="-1">情态动词的被动结构 <a class="header-anchor" href="#情态动词的被动结构" aria-label="Permalink to &quot;情态动词的被动结构 {#情态动词的被动结构}&quot;">​</a></h2><p>must be tested 表示必须被检测，should be tested 通常表示建议或较弱义务，may be tested 表示许可或可能；具体含义取决于语境。结构为情态动词 + be + 过去分词，不能省略 be。标准文件常用被动突出对象，但应在必要时加 by 短语说明责任人。课堂中的 must 只是练习设定的要求，不能据此推断现实法律规定。</p><p><strong>L8 原创例句：</strong> Under our workshop rules, every sample must be checked before it is packed.</p><p>按照我们工作坊的规定，每个样品都必须在包装前接受检查。</p><p><strong>易错：</strong> every sample must checked 缺少 be；必须写 must be checked。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">Lesson 8</a></p>',55)])])}const g=n(a,[["render",t]]);export{f as __pageData,g as default};
